 document.querySelectorAll('[data-edit-customer]').forEach(b=>b.onclick=()=>{const c=db.customers.find(x=>x.id===b.dataset.editCustomer);if(!c)return;modal(`<div class="modalhead"><h2>✏️ Edit customer</h2><button class="close" data-close>×</button></div><form id="editCustomerForm" class="formgrid" style="margin-top:14px"><input type="hidden" name="id" value="${esc(c.id)}">${field('Full name','name',c.name,'text','Customer full name.')}${field('WhatsApp / mobile','phone',c.phone,'tel','Customer contact number.')}${field('Email','email',c.email||'','email','Optional.')}${field('Service','service',c.service||'Lawn restoration','text','Main service.')}${field('Property address','address',c.address||'','text','Service address.',true)}${field('Access notes','access',c.access||'','text','Gate, parking and access instructions.',true)}<div class="field full"><button class="btn">Save customer</button></div></form>`);attachModalHandlers()});
